def countKnightWalks(n, k, sr, sc, tr, tc):
    MOD = 10 ** 9 + 7
    moves = [(1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)]
    cur = [[0] * n for _ in range(n)]
    cur[sr][sc] = 1
    for _ in range(k):
        nxt = [[0] * n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                v = cur[r][c]
                if v:
                    for dr, dc in moves:
                        a, b = r + dr, c + dc
                        if 0 <= a < n and 0 <= b < n:
                            nxt[a][b] += v
        cur = [[x % MOD for x in row] for row in nxt]
    return cur[tr][tc]
